import { test, expect } from '@playwright/test';
import { resetAndSeed } from '../support/seed';

test.describe('round divides', () => {
  test('round divides', { tag: '@functionality' }, async ({ page }) => {
    await resetAndSeed({people: [{id: 1, name: "Ada", alpha: 3, beta: 5, gamma: 4}, {id: 2, name: "Ben", alpha: 2, beta: 6, gamma: 3}, {id: 3, name: "Cam", alpha: 5, beta: 4, gamma: 9}, {id: 4, name: "Dot", alpha: 4, beta: 3, gamma: 2}, {id: 5, name: "Sid", alpha: 4, beta: 2, gamma: 0}, {id: 9, name: "Hz", alpha: 2, beta: 5, gamma: 0, hold: true}, {id: 6, name: "Moe", alpha: 2, beta: 4, gamma: null}], patrons: [{personId: 1, patronId: 2}, {personId: 1, patronId: 3}]});
    await page.goto('/');

    await expect(page.getByTestId('person-row-1').getByTestId('concept-third')).toHaveText('12');
    await expect(page.getByTestId('person-row-2').getByTestId('concept-third')).toHaveText('10');
    await expect(page.getByTestId('person-row-3').getByTestId('concept-third')).toHaveText('21');
    await expect(page.getByTestId('person-row-4').getByTestId('concept-third')).toHaveText('4');
    await expect(page.getByTestId('person-row-5').getByTestId('concept-third')).toHaveText('-3');
    await expect(page.getByTestId('person-row-6').getByTestId('concept-third')).toHaveText('n/a');
    await expect(page.getByTestId('person-row-9').getByTestId('concept-third')).toHaveText('3');
    await expect(page.getByTestId('person-row-1').getByTestId('concept-quarter')).toHaveText('9');
    await expect(page.getByTestId('person-row-2').getByTestId('concept-quarter')).toHaveText('8');
    await expect(page.getByTestId('person-row-3').getByTestId('concept-quarter')).toHaveText('16');
    await expect(page.getByTestId('person-row-4').getByTestId('concept-quarter')).toHaveText('3');
    await expect(page.getByTestId('person-row-5').getByTestId('concept-quarter')).toHaveText('-2');
    await expect(page.getByTestId('person-row-6').getByTestId('concept-quarter')).toHaveText('n/a');
    await expect(page.getByTestId('person-row-9').getByTestId('concept-quarter')).toHaveText('2');
    await expect(page.getByTestId('person-row-1').getByTestId('concept-norm')).toHaveText('12');
    await expect(page.getByTestId('person-row-2').getByTestId('concept-norm')).toHaveText('6');
    await expect(page.getByTestId('person-row-3').getByTestId('concept-norm')).toHaveText('40');
    await expect(page.getByTestId('person-row-4').getByTestId('concept-norm')).toHaveText('-12');
    await expect(page.getByTestId('person-row-5').getByTestId('concept-norm')).toHaveText('-32');
    await expect(page.getByTestId('person-row-6').getByTestId('concept-norm')).toHaveText('n/a');
    await expect(page.getByTestId('person-row-9').getByTestId('concept-norm')).toHaveText('-16');
  });
});

